import {sources,vendorSources,stack,costActions,flows,decisions,demoRecords} from './enrichment-data.mjs';
import {fields,issues,suggestTags,costModel} from './enrichment-rules.mjs';
import {createWorkbench} from './workbench-ui.mjs';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state={authUnavailable:false,me:null,records:[],studies:[],selected:null,kind:'all',status:'all',search:'',workflow:'permanent',route:'',request:0};
const money=v=>new Intl.NumberFormat('en-AU',{style:'currency',currency:'AUD',maximumFractionDigits:0}).format(v),decimal=v=>Number(v).toLocaleString('en-AU',{maximumFractionDigits:1}),date=v=>new Date(v).toLocaleString('en-AU',{dateStyle:'medium',timeStyle:'short'});
const badge=(text,colour='')=>`<span class="pill ${colour}">${esc(text)}</span>`;
const title=(name,sub,actions='')=>`<div class="page-heading"><div><p class="eyebrow">PHILLIP RILEY / WORKSPACE</p><h1>${name}</h1><p>${sub}</p></div>${actions}</div>`;
const stat=(label,value,note)=>`<article><span>${label}</span><strong>${value}</strong><small>${note}</small></article>`;
const btn=(text,action,cls='secondary',extra='')=>`<button class="${cls}" data-action="${action}" ${extra}>${text}</button>`;
const signed=()=>state.me?true:(toast(state.authUnavailable?'Staff sign-in is pending setup. You can browse the public guides.':'Sign in to save records and decisions.'),false);
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',6500);}
async function api(path,options={}){const response=await fetch('/api'+path,{...options,credentials:'same-origin',redirect:'manual',headers:{'Content-Type':'application/json','x-prg-request':'1',...options.headers},...(options.body?{body:JSON.stringify(options.body)}:{})});if(response.type==='opaqueredirect'||[301,302,303,307,308].includes(response.status))throw Object.assign(new Error('Your session has ended. Sign in with your work email again. Your input has been kept.'),{status:401});let data;try{data=await response.json();}catch{throw new Error('The workspace is unavailable. Your input has been kept.');}if(!response.ok)throw Object.assign(new Error(data.error||'Request failed.'),{status:response.status});return data;}
function download(filename,value,type='application/json'){const a=document.createElement('a');const url=URL.createObjectURL(new Blob([typeof value==='string'?value:JSON.stringify(value,null,2)],{type}));a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function modal(html){const d=$('#modal');d.innerHTML=`<button class="close small" data-action="close">Close</button>${html}<p class="error" id="modal-error" role="alert"></p>`;if(!d.open)d.showModal();}
const sampleNotice=`<div class="notice">Synthetic rehearsal only. Saved reviews and exports work; JobAdder, ROI-AI and live AI are not connected. Do not enter live candidate or client details.</div>`;
const recordStatus=r=>{const f=r.payload.fields;return f.some(x=>x.decision==='pending'||x.decision==='held')?'Needs review':f.some(x=>x.decision==='accepted')?'Reviewed':'Rejected';};
function filters(){return `<div class="toolbar"><label>Find a record<input id="search" placeholder="Name or record ID" value="${esc(state.search)}"></label><label>Record type<select id="kind"><option value="all">All records</option><option value="candidate" ${state.kind==='candidate'?'selected':''}>Candidates</option><option value="contact" ${state.kind==='contact'?'selected':''}>Client contacts</option></select></label><label>Review status<select id="status"><option value="all">All statuses</option>${['Needs review','Reviewed','Rejected'].map(s=>`<option ${state.status===s?'selected':''}>${s}</option>`).join('')}</select></label></div>`;}
function queue(){
 const all=state.records,approved=all.flatMap(r=>r.payload.fields).filter(f=>f.decision==='accepted'&&!issues(f).length).length,blocked=all.flatMap(r=>r.payload.fields).filter(f=>issues(f).length).length;
 const records=all.filter(r=>(state.kind==='all'||r.kind===state.kind)&&(state.status==='all'||recordStatus(r)===state.status)&&`${r.name} ${r.external_id}`.toLowerCase().includes(state.search.toLowerCase()));
 if(!records.some(r=>r.id===state.selected))state.selected=records[0]?.id||null;const selected=records.find(r=>r.id===state.selected);
 return title('Review queue','Check the source. Resolve the gaps. Keep JobAdder accurate.',`<div class="actions">${btn('Import rehearsal batch','import')}${btn('Load demonstration','seed','')}</div>`)+sampleNotice+`<div class="stats">${stat('Saved records',all.length,'Candidate and client-contact cohorts')}${stat('Approved fields',approved,'Currently pass the evidence checks')}${stat('Fields with evidence gaps',blocked,'Need a source, identity check or resolution')}</div>${filters()}<div class="queue-layout"><div class="record-list">${records.map(r=>`<button class="record-card ${r.id===state.selected?'selected':''}" data-action="select" data-id="${r.id}" aria-pressed="${r.id===state.selected}">${badge(r.kind==='candidate'?r.workflow:'Client contact','blue')}<small>${esc(r.external_id)}</small><strong>${esc(r.name)}</strong><small>${esc(r.payload.stage)}</small><small>${recordStatus(r)} · ${r.payload.fields.length} proposed fields</small></button>`).join('')||`<section class="panel empty"><h2>${all.length?'No matches':'Start with a rehearsal'}</h2><p>${all.length?'Change the search or filters.':'Load four fictional records to try clean evidence, stale availability, a conflict and an unconfirmed identity.'}</p>${!all.length?btn(state.me?'Load demonstration':'Sign in to begin',state.me?'seed':'signin',''):''}</section>`}</div><section id="record-detail">${selected?detail(selected):`<div class="panel"><h2>What enrichment means here</h2><p>Fill a missing field or refresh an outdated one using evidence that a consultant can inspect.</p><ol><li>Bring a record and a source excerpt.</li><li>Check the person, date and proposed value.</li><li>Accept, reject or hold each field.</li><li>Export accepted changes for manual mapping and review.</li></ol><p class="panel-note">No candidate ranking, automated suitability decisions, compliance claims or automatic contact.</p><a href="#guide">Read the working method</a></div>`}</section></div>`;
}
function detail(r){const p=r.payload,canReview=['admin','reviewer'].includes(state.me?.role);return `<div class="panel"><div class="panel-head"><div><p class="eyebrow">${esc(r.external_id)} · VERSION ${r.version}</p><h2>${esc(r.name)}</h2></div>${badge(recordStatus(r),'blue')}</div><p class="muted">${esc(p.stage)} · ${esc(r.author||'Saved record')}</p><div class="actions">${r.owner_id===state.me?.id?btn('Edit evidence','edit','secondary small',`data-id="${r.id}"`):''}${btn('Review history','history','secondary small',`data-id="${r.id}"`)}${btn('Export approved fields','export','small',`data-id="${r.id}"`)}</div>${!canReview?'<p class="status-line">A reviewer or owner can approve fields. Authors can prepare and correct evidence.</p>':''}${p.fields.map(f=>{const flags=issues(f);return `<article class="field"><div class="field-head"><h3>${esc(fields[f.key].label)}</h3>${badge(f.decision,f.decision==='accepted'?'green':f.decision==='rejected'?'red':f.decision==='held'?'amber':'')}</div><div class="compare"><div class="value"><small>Current value</small><p>${esc(f.current)||'— Missing —'}</p></div><div class="value new"><small>Proposed value</small><p>${esc(f.proposed)||'— Missing —'}</p></div></div><div class="source"><strong>${esc(f.source.reference)||'Source reference missing'}</strong><blockquote>“${esc(f.source.quote)}”</blockquote><small>${esc(f.source.type.replaceAll('_',' '))} · ${esc(f.source.date)||'Date missing'} · Identity ${f.source.identityConfirmed?'confirmed by preparer':'not confirmed'}</small></div>${f.conflict?`<p class="status-line">Conflicting evidence: ${esc(f.resolution)||'Resolution required.'}</p>`:''}${flags.length?`<div class="notice warning"><strong>Evidence checks</strong><ul>${flags.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`:`<p class="status-line">Evidence checks passed. Reviewer must still verify meaning and accuracy.</p>`}${f.reviewer?`<p class="status-line">${esc(f.reviewer)} · ${date(f.reviewedAt)}${f.note?`<br>${esc(f.note)}`:''}</p>`:''}${canReview?`<div class="actions">${btn('Accept field','review','small',`data-id="${r.id}" data-field="${f.key}" data-decision="accepted" ${flags.length?'disabled':''}`)}${btn('Hold','review','secondary small',`data-id="${r.id}" data-field="${f.key}" data-decision="held"`)}${btn('Reject','review','danger small',`data-id="${r.id}" data-field="${f.key}" data-decision="rejected"`)}</div>`:''}</article>`;}).join('')}</div>`;}
function workflow(){const type=state.workflow;return title('Recruitment workflow','Enrichment supports the existing process at specific points. Consultants retain decisions.')+`<div class="tabs">${btn('Permanent recruitment','flow',''+(type==='permanent'?'active':''),'data-value="permanent"')}${btn('Contract recruitment','flow',''+(type==='contract'?'active':''),'data-value="contract"')}</div><div class="notice">${type==='permanent'?'S2 · QM-PRO-002, version 9':'S3 · QM-PRO-006, version 7'} · issued 17 September 2026. Blue steps include proposed enrichment work; amber steps need explicit human checks. This is a summary of the supplied process, not a replacement SOP.</div><div class="flow">${flows[type].map(([name,text,cls])=>`<article class="${cls}"><h3>${name}</h3><p>${text}</p>${cls==='enrich'?badge('Proposed insertion','blue'):cls==='gate'?badge('Human checkpoint','amber'):''}</article>`).join('')}</div><section class="panel" style="margin-top:22px"><h2>Keep the exceptions visible</h2>${type==='permanent'?'<p>The supplied SOP flags a New Zealand restriction on sharing employment contracts with recruitment companies. Route that case to the process owner; do not auto-request or store the contract. This workspace records the SOP instruction, not a separately verified legal conclusion.</p>':'<p>The contract diagram hands off to QM-PRO-003. Obtain that Operations process before designing contractor onboarding. PLSL, work-rights and medical checks cannot be established from enrichment suggestions.</p>'}<p>Authority to Represent, contact permission and verified compliance are different things. A fresh email address or a skill tag does not establish any of them.</p><a href="#evidence">See source references and open decisions</a></section>`;}
function toolsPage(){return title('Tools & overlap','Work through the stack PRG already has before adding another system.')+`<div class="notice warning">Documented does not mean independently verified in a live account. The workbook also contains roadmap items and tools whose current status is unresolved.</div><section class="panel"><div class="panel-head"><h2>The documented operating path</h2>${badge('S1 · technology overview','blue')}</div><div class="three-col"><div><h3>Before a placement</h3><p>LinkedIn / SEEK / database → JobAdder<br>ROI-AI ↔ JobAdder<br>8x8 → CoRecruit → JobAdder</p></div><div><h3>After a placement</h3><p>JobAdder → Zapier → Google Chat / Mailchimp<br>JobAdder → Xero / OneUp</p></div><div><h3>Contractor operations</h3><p>Astute → Xero / OneUp<br>Operations handoff governed by QM-PRO-003</p></div></div><p class="panel-note">Arrows summarise the supplied overview. Confirm connection direction, fields, triggers and error handling with the system owner.</p></section><section class="panel"><div class="table-wrap"><table><thead><tr><th>Tool / purpose</th><th>Documented role</th><th>Decision to make</th></tr></thead><tbody>${stack.map(x=>`<tr><td>${esc(x.name)}<small>${esc(x.area)}<br>${esc(x.status)}</small></td><td>${esc(x.role)}</td><td>${badge(x.action,x.action.includes('Reconcile')?'amber':'blue')}<p>${esc(x.check)}</p></td></tr>`).join('')}</tbody></table></div></section><section class="panel"><h2>What to compare before choosing a route</h2><div class="table-wrap"><table><thead><tr><th>Route</th><th>Best reason to use it</th><th>What it must prove</th></tr></thead><tbody><tr><td>Configure existing tools first</td><td>Fits JobAdder and avoids another subscription where capability is included.</td><td>Exact licence scope, field coverage, accuracy, review process and incremental cost.</td></tr><tr><td>Add a specialist enrichment module</td><td>Existing tools cannot provide reliable source-backed updates.</td><td>Coverage on PRG’s target market, cost per useful record, access terms and correction flow.</td></tr><tr><td>Use an approved general AI tool</td><td>Extracts structured suggestions from permitted internal evidence.</td><td>Grounded output, predictable review time and approved handling. It cannot establish fresh contact details by guessing.</td></tr><tr><td>Build a small custom connection</td><td>A measured, valuable gap remains after trying the routes above.</td><td>Support owner, maintenance, test environment, scoped access, retry safety and rollback. This review workspace is not that live integration.</td></tr></tbody></table></div></section>`;}
const costInputs=[['currentAnnual','Current annual spend (AUD)'],['removablePercent','Contractually removable share (%)'],['replacementAnnual','Replacement licences / year (AUD)'],['providerAnnual','Enrichment or AI usage / year (AUD)'],['supportAnnual','Incremental support / year (AUD)'],['transitionCost','One-off transition cost (AUD)'],['recordsPerMonth','Records processed per month'],['manualMinutes','Manual minutes per record'],['assistedMinutes','Assisted minutes including review'],['hourlyCost','Loaded staff cost per hour (AUD)']];
const numberField=([key,label],value='')=>`<label>${label}<input name="${key}" type="number" min="0" ${key==='removablePercent'?'max="100"':''} step="any" required value="${value}" placeholder="Enter a measured value or 0"></label>`;
function costResults(x){const r=costModel(x);return `<div class="stats">${stat('Net cash change · year one',money(r.firstYearCash),'Avoidable spend less recurring and transition costs')}${stat('Net cash change · recurring',money(r.recurringCash),'Annual cash impact after the transition')}${stat('Annual capacity change',`${decimal(r.hours)} hours`,'Time released or added; not a cash saving')}</div><p>Capacity value: <strong>${money(r.capacityValue)}</strong> at the entered staff rate. Keep this separate from cash savings. Payback: <strong>${r.paybackMonths===null?'not reached from recurring cash savings':decimal(r.paybackMonths)+' months'}</strong>.</p><p class="status-line">Avoidable spend ${money(r.annualAvoidable)} − incremental recurring cost ${money(r.recurring)} − transition ${money(x.transitionCost)} = year-one cash change. This is a steady-state annual model, excluding GST; adjust for renewal timing before approval.</p>`;}
function costs(){return title('Cost review','Find avoidable spend and measure useful work. Keep cash savings separate from time saved.')+`<div class="notice warning"><strong>Actual savings are not yet known.</strong> S4’s Cost p/a column is blank. No tool has been classified as a confirmed cancellation saving.</div><section class="panel"><h2>Recommended order of review</h2>${costActions.map((x,i)=>`<details ${i===0?'open':''}><summary>${badge(x.priority,'blue')} ${x.title}</summary><p>${x.why}</p><p><strong>Next action:</strong> ${x.steps}</p><p><strong>Decision condition:</strong> ${x.condition}</p><small>${x.evidence} · Suggested owner: ${x.owner}</small></details>`).join('')}</section><section class="panel"><div class="panel-head"><h2>Build a cost case</h2>${btn('Load illustrative example','cost-example','secondary small')}</div><p class="muted">Enter annual amounts in AUD excluding GST. Include incremental support and all provider usage. No default savings assumptions are prefilled.</p><form id="cost-form"><div class="form-grid"><label class="full">Case name<input name="name" required maxlength="160" placeholder="For example: enrichment licence review"></label><label>Evidence basis<select name="basis"><option value="illustrative">Illustrative assumptions</option><option value="invoice_based">Invoice and usage evidence</option></select></label><label>Evidence references<input name="evidence" maxlength="2000" placeholder="Invoice dates, renewal terms, usage sample"></label>${costInputs.map(x=>numberField(x)).join('')}</div><div class="actions"><button type="button" data-action="calculate">Calculate</button><button class="secondary" type="submit">Save cost case</button></div><p class="form-error error" role="alert"></p></form><div id="cost-result"></div></section><section class="panel"><h2>Saved cost cases</h2>${studyList('cost')}</section>`;}
const pilotInputs=[['records','Records attempted'],['useful','Records with a useful accepted update'],['proposed','Fields proposed'],['accepted','Fields accepted'],['audited','Proposed fields independently audited'],['correct','Audited fields confirmed correct'],['criticalErrors','Critical errors found'],['manualMinutes','Total manual time for comparable work (minutes)'],['assistedMinutes','Total assisted time including review / rework (minutes)'],['totalCost','Total pilot cost including review labour (AUD)']];
function pilot(){return title('Pilot & results','Prove that enrichment produces accurate, useful records at an acceptable cost.')+`<div class="notice">Proposed starting point: 50 candidate records from one desk, including incomplete, stale, conflicting and already-complete examples. Test client contacts separately. Agree the cohort and thresholds with PRG.</div><div class="two-col"><section class="panel"><h2>Candidate pilot</h2><p>Start with specialism and skills evidenced in candidate-supplied material. Add current title/employer only with recent evidence. Treat availability as a direct confirmation.</p><ul><li>Measure manual baseline on comparable records.</li><li>Test the existing licensed tool first.</li><li>Review every change in the first cohort.</li><li>Independently audit the proposed fields, including rejected ones.</li><li>Keep attempts with no useful result in the denominator.</li></ul></section><section class="panel"><h2>Proposed acceptance gates</h2><ul><li>Zero critical identity, disclosure or unsupported compliance errors.</li><li>At least 95% source-backed accuracy on audited fields.</li><li>Positive net time saved after review and rework.</li><li>A useful-record cost accepted by the budget owner.</li><li>Export / mapping rehearsal completed and rollback documented.</li></ul><p class="panel-note">These are proposed pilot gates, not PRG-approved targets. A small sample does not establish production accuracy.</p></section></div><section class="panel"><h2>Work through evidence gates</h2><div class="flow"><article><h3>Define & baseline</h3><p>Agree fields, scope, source permission, freshness rules, ownership and manual time.</p></article><article><h3>Trial existing tools</h3><p>Record every attempt, provider cost, review minutes and corrected errors.</p></article><article><h3>Validate & decide</h3><p>Audit accuracy and useful coverage. Retest failures before increasing volume.</p></article><article><h3>Handover & operate</h3><p>Document configuration, mappings, responsibilities, exception queue, recovery and cost limits.</p></article></div></section><section class="panel"><h2>Record a pilot result</h2><form id="pilot-form"><div class="form-grid"><label>Run name<input name="name" required maxlength="160" placeholder="Cohort / tool / run"></label><label>Evidence basis<select name="basis"><option value="rehearsal">Synthetic rehearsal</option><option value="observed">Observed approved pilot (aggregate only)</option></select></label>${pilotInputs.map(x=>numberField(x)).join('')}<label class="full">Cohort, method and evidence reference<textarea name="evidence" required maxlength="2000" placeholder="Scope, sampling method, reviewer and evidence location. Use aggregate results; no candidate details."></textarea></label></div><div class="actions"><button>Save pilot result</button></div><p class="form-error error" role="alert"></p></form></section><section class="panel"><h2>Saved results</h2>${studyList('pilot')}</section>`;}
function studyList(type){const list=state.studies.filter(s=>s.type===type);return list.length?`<div class="table-wrap"><table><thead><tr><th>Name / evidence</th><th>Result</th><th>Saved</th><th>Detail</th></tr></thead><tbody>${list.map(s=>{const p=s.payload,r=p.results;return `<tr><td>${esc(s.name)}<small>${esc(p.basis||p.status)}</small></td><td>${type==='cost'?`${money(r.firstYearCash)} year-one cash<br>${decimal(r.hours)} hours capacity`:type==='pilot'?`${r.accuracy===null?'Not audited':decimal(r.accuracy)+'% audited accuracy'}<br>${decimal(r.coverage)}% useful coverage<br>${p.inputs.criticalErrors} critical errors`:esc(p.note)}</td><td>${date(s.created_at)}</td><td>${btn('View','study','secondary small',`data-id="${s.id}"`)}</td></tr>`;}).join('')}</tbody></table></div>`:'<p class="muted">No saved evidence yet. Results remain unknown until a review is recorded.</p>';}
function evidence(){return title('Sources & decisions','Separate documented facts, vendor claims and choices that PRG still needs to make.')+`<section class="panel"><div class="panel-head"><h2>Internal source register</h2>${badge('Reviewed 2 Oct 2026','blue')}</div>${sources.map(s=>`<details open><summary>${s.id} · ${s.title}</summary><p>${s.finding}</p><small class="break">${s.file}<br>${s.location}<br>${s.basis}</small></details>`).join('')}<p class="panel-note">Original files are retained locally and are not included in this Site or the public project repository.</p></section><section class="panel source-list"><h2>Public vendor checks</h2><p class="muted">Checked 2 October 2026. Marketing claims establish advertised capability, not PRG’s entitlement, configuration or measured results.</p>${vendorSources.map(s=>`<a href="${s.url}" target="_blank" rel="noreferrer">${s.title}</a><p>${s.note}</p>`).join('')}</section><section class="panel"><h2>Decisions needed from PRG</h2>${decisions.map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</section><section class="panel"><h2>Record a decision or finding</h2><form id="decision-form"><div class="form-grid"><label>Decision / question<input name="name" required maxlength="160"></label><label>Status<select name="status"><option value="open">Open</option><option value="confirmed">Confirmed with evidence</option><option value="deferred">Deferred</option></select></label><label>Responsible role<input name="owner" maxlength="120" placeholder="For example: ATS administrator"></label><label>Evidence reference<input name="evidence" maxlength="2000" placeholder="Meeting date, approved policy or contract reference"></label><label class="full">Finding / next action<textarea name="note" required maxlength="4000"></textarea></label></div><div class="actions"><button>Save decision entry</button></div><p class="form-error error" role="alert"></p></form></section><section class="panel"><h2>Decision log</h2>${studyList('decision')}</section>`;}
function guide(){return title('Staff guide','A consistent working method for consultants, reviewers and operations. JobAdder remains the source of truth.')+`<section class="panel"><h2>Start with your task</h2><div class="staff-start-grid"><a href="#work"><strong>Consultants</strong><span>Open a permanent, contract or client research case. Record the next action and evidence.</span></a><a href="#queue"><strong>Enrichment reviewers</strong><span>Compare proposed values with their sources. Accept, hold or reject each field.</span></a><a href="#workflow"><strong>Operations</strong><span>Check the relevant process and prepare the required handoff. Confirm remaining checks in the source system.</span></a><a href="#pilot"><strong>Managers & tool owners</strong><span>Record pilot measurements, check cost assumptions and resolve setup decisions.</span></a></div><p class="panel-note">These links guide you to the relevant task; they do not grant permissions or change your account role.</p></section><section class="panel"><h2>Your daily routine</h2><ol><li><a href="#home">Check Overview</a> for your saved cases, due dates and available reviews.</li><li><a href="#work">Open your work board</a>, choose a case and record the current-stage evidence.</li><li><a href="#platforms">Use Platform hub</a> to save your approved workspace links and open the tool needed for the task.</li><li>Review linked enrichment before exporting approved fields or preparing a handoff.</li><li>Complete the actual update in the authorised system, then record its outcome reference here.</li></ol></section><section class="panel"><h2>Access & company rollout</h2><p>Sign in with your own account. Work items, platform shortcuts and study entries are saved to that account. An assignee label does not share a case or notify a colleague. Enrichment review access follows the configured reviewer and administrator roles.</p><p>This public pilot uses fictional examples. Company-wide shared queues, staff membership, delegated assignments and production data access are not configured yet.</p><p>Before rollout, the company administrator needs to confirm the staff access list, reviewer roles, approved hosting and retention, and integration owners. Agree who can view, edit and approve each type of record before enabling shared work.</p></section><section class="panel"><h2>Try the enrichment review</h2><ol><li>Load the synthetic examples or import a synthetic JSON batch.</li><li>Review each field alongside its source, date and current value.</li><li>Correct the evidence, or record an accept / hold / reject decision.</li><li>Export only approved fields that still pass the evidence rules.</li><li>Save aggregate pilot results, cost assumptions and project decisions.</li></ol><p>Record changes, decisions and exports are saved in a database and attributed to the signed-in account. Authors can edit their own records; reviewers and the owner can review. Editing evidence resets all previous field decisions.</p></section><div class="two-col"><section class="panel"><h2>Where AI fits</h2><p>In a live pilot, an approved enrichment provider or AI tool would propose field values from permitted evidence. This workspace checks and records the review of those suggestions.</p><p>The evidence helper highlights exact phrases using a small dictionary. It runs locally and is <strong>not generative AI</strong>. No prompt, CV or internal document is sent to an AI provider.</p><p>The earlier general chatbot is retired from this workflow. Live model access, provider selection and PRG-approved data handling remain prerequisites for an AI connection.</p></section><section class="panel"><h2>Before using live data</h2><ul><li>Confirm PRG-approved hosting, access and retention.</li><li>Obtain the referenced internal privacy policy and field dictionary.</li><li>Confirm tool entitlements and permitted sources.</li><li>Test scoped JobAdder access and field mapping in an approved environment.</li><li>Use dry runs, current-value comparison, duplicate protection and rollback before any write.</li></ul><p>No live import or ATS write is enabled here.</p></section></div><section class="panel"><h2>Proposed freshness rules</h2><div class="table-wrap"><table><thead><tr><th>Field</th><th>Maximum source age</th><th>Reason</th></tr></thead><tbody><tr><td>Skills / specialism</td><td>365 days</td><td>A starting review interval, not a guarantee of competency.</td></tr><tr><td>Title / employer / company / location</td><td>180 days</td><td>Employment and organisation details can change.</td></tr><tr><td>Business contact details</td><td>90 days</td><td>Needs a verified-provider result or direct confirmation.</td></tr><tr><td>Availability</td><td>30 days</td><td>Needs current candidate confirmation.</td></tr></tbody></table></div><p class="panel-note">Agree these rules with PRG. Every accepted field still needs a reviewer. Source age is recalculated before export.</p></section><section class="panel"><h2>Need help or a process decision?</h2><p>Use <a href="#evidence">Sources & decisions</a> to record an unresolved process question and responsible role. Use <a href="#platforms">Platform hub</a> to check the relevant tool prerequisites. Decision entries are saved to your account; they do not send a support request or notify the named role.</p></section>`;}
async function archive(){const data=await Promise.all([api('/drafts'),api('/cases'),api('/measurements'),api('/priorities')]);return title('Archived prototype records','Read-only historical examples. These are not evidence of PRG operating results.')+`<div class="notice warning">Preserved for continuity. Earlier cost cases and priority scores were hypothetical; do not use them to support a current savings claim.</div>${data.map((d,i)=>`<section class="panel"><h2>${['Workflow drafts','Illustrative cost cases','Old trial measurements','Hypothetical priorities'][i]}</h2>${Object.values(d)[0].length?Object.values(d)[0].map(item=>`<details><summary>${esc(item.title||item.name||item.label)} · ${date(item.created_at)}</summary><pre class="code">${esc(JSON.stringify(item,null,2))}</pre></details>`).join(''):'<p>No saved records.</p>'}</section>`).join('')}`;}
const workbench=createWorkbench({state,api,esc,toast,modal,download,render,detail});
async function render(){
 const ticket=++state.request,hash=location.hash.slice(1),route=['home','work','platforms','queue','workflow','stack','costs','pilot','evidence','guide','archive'].includes(hash)?hash:'home';state.route=route;document.querySelector('#crumb').textContent=({home:'Overview',work:'Work board',platforms:'Platform hub',queue:'Enrichment review',workflow:'Process map',stack:'Stack review',costs:'Cost review',pilot:'Pilot results',evidence:'Sources & decisions',guide:'Staff guide',archive:'Earlier records'})[route];document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+route));
 try{if(state.me&&['home','work','platforms','queue','costs','pilot','evidence'].includes(route)){const [r,s]=await Promise.all([api('/enrichment/records'),api('/enrichment/studies')]);if(ticket!==state.request)return;state.records=r.records;state.studies=s.studies;await workbench.load();}
 const html=['home','work','platforms'].includes(route)?workbench.view(route):route==='workflow'?workflow():route==='stack'?toolsPage():route==='costs'?costs():route==='pilot'?pilot():route==='evidence'?evidence():route==='guide'?guide():route==='archive'?(state.me?await archive():title('Earlier records','Sign in to view saved records.')):queue();if(ticket!==state.request)return;$('#main').innerHTML=(state.authUnavailable?'<div class="notice warning"><strong>Public preview · staff sign-in pending.</strong> Explore workflows, platforms and guidance. Saving cases, reviews and measurements will be available after staff access is configured.</div>':'')+html;
 }catch(e){if(ticket!==state.request)return;$('#main').innerHTML=title('Workspace unavailable','Saved data could not be loaded.')+`<div class="notice warning">${esc(e.message)}</div>${btn('Try again','reload')}`;}
}
function reviewDialog(r,key,decision){const f=r.payload.fields.find(f=>f.key===key);modal(`<h2>${decision==='accepted'?'Accept':decision==='held'?'Hold':'Reject'} ${esc(fields[key].label.toLowerCase())}</h2><p>${esc(r.name)} · proposed value: <strong>${esc(f.proposed)}</strong></p><form id="review-form" data-id="${r.id}" data-field="${key}" data-decision="${decision}" data-version="${r.version}"><label>Review note<textarea name="note" ${decision==='accepted'?'':'required'} maxlength="2000"></textarea></label>${decision==='accepted'?'<label class="check"><input type="checkbox" name="confirmed" required>I checked the identity, supporting source and proposed value. This is an enrichment decision, not a hiring or compliance approval.</label>':''}<div class="actions"><button>Save decision</button></div></form>`);}
function editDialog(r){modal(`<h2>Edit source evidence</h2><p>Changing any evidence resets every field decision on this record. Use synthetic material only.</p><form id="edit-form" data-id="${r.id}" data-version="${r.version}"><label>Display name<input name="name" value="${esc(r.name)}" required maxlength="120"></label><label>Workflow stage<input name="stage" value="${esc(r.payload.stage)}" maxlength="160"></label>${r.payload.fields.map((f,i)=>`<fieldset class="panel" style="margin-top:20px"><legend>${esc(fields[f.key].label)}</legend><div class="form-grid"><label>Current value<input name="current-${i}" value="${esc(f.current)}" maxlength="1000"></label><label>Proposed value<input name="proposed-${i}" value="${esc(f.proposed)}" maxlength="1000"></label><label>Source type<select name="type-${i}">${['cv','candidate_confirmation','consultant_note','company_website','verified_provider','contact_confirmation'].map(s=>`<option value="${s}" ${s===f.source.type?'selected':''}>${s.replaceAll('_',' ')}</option>`).join('')}</select></label><label>Source date<input type="date" name="date-${i}" value="${esc(f.source.date)}"></label><label class="full">Source reference<input name="reference-${i}" value="${esc(f.source.reference)}" maxlength="300"></label><label class="full">Exact supporting excerpt<textarea name="quote-${i}" maxlength="4000">${esc(f.source.quote)}</textarea></label><div class="full">${btn('Find exact skill phrases','tags','secondary small',`data-index="${i}"`)}<div id="tags-${i}" class="status-line"></div></div><label class="check full"><input type="checkbox" name="identity-${i}" ${f.source.identityConfirmed?'checked':''}>Source identity confirmed</label><label class="check full"><input type="checkbox" name="conflict-${i}" ${f.conflict?'checked':''}>This field has conflicting evidence</label><label class="full">Conflict resolution<textarea name="resolution-${i}" maxlength="2000">${esc(f.resolution)}</textarea></label></div></fieldset>`).join('')}<button>Save evidence and reset reviews</button></form>`);}
function values(form,definitions){const fd=new FormData(form),out={};for(const [key]of definitions){const v=fd.get(key);if(v===null||String(v).trim()==='')throw new Error('Fill in every numeric field. Enter 0 where there is no cost or activity.');out[key]=Number(v);if(!Number.isFinite(out[key])||out[key]<0||(key==='removablePercent'&&out[key]>100))throw new Error('Check the numeric values.');}return out;}
document.addEventListener('click',async event=>{const b=event.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,r=state.records.find(r=>r.id===b.dataset.id);try{
 if(a==='close')return $('#modal').close();if(a==='signin')return location.href='/signin-with-chatgpt';if(a==='reload')return render();
 if(a==='select'){state.selected=b.dataset.id;$('#main').innerHTML=queue();return;}
 if(a==='flow'){state.workflow=b.dataset.value;$('#main').innerHTML=workflow();return;}
 if(a==='seed'){if(!signed())return;b.disabled=true;const ids=new Set(state.records.filter(r=>r.owner_id===state.me.id).map(r=>r.external_id));const records=demoRecords().filter(r=>!ids.has(r.externalId));if(!records.length)return toast('The demonstration records are already saved. Use Edit evidence to change them.');await api('/enrichment/records',{method:'POST',body:{syntheticOnly:true,records}});toast('Four demonstration scenarios are available in the saved queue.');await render();return;}
 if(a==='import'){if(!signed())return;modal(`<h2>Import a synthetic batch</h2><p>Up to 25 records. Existing IDs are rejected; imports do not overwrite records. Use the template to see allowed fields and evidence structure.</p>${btn('Download JSON template','template','secondary small')}<form id="import-form"><label>JSON file<input name="file" type="file" accept=".json,application/json" required></label><label class="check"><input name="confirmed" type="checkbox" required>I confirm that every record is synthetic and contains no real candidate or client data.</label><div class="actions"><button>Validate and import</button></div></form>`);return;}
 if(a==='template')return download('prg-synthetic-enrichment-template.json',{records:demoRecords()});
 if(a==='review')return reviewDialog(r,b.dataset.field,b.dataset.decision);if(a==='edit')return editDialog(r);
 if(a==='tags'){const i=b.dataset.index,q=$(`[name="quote-${i}"]`).value,tags=suggestTags(q);$(`#tags-${i}`).textContent=tags.length?'Exact phrases: '+tags.map(t=>t.value).join(' · '):'No dictionary phrases found. Add evidence manually; do not infer a skill.';return;}
 if(a==='history'){const d=await api('/enrichment/records/'+r.id);modal(`<h2>Review history</h2><p>${esc(r.name)} · every saved change and export</p><div class="history">${d.events.map(e=>`<p><strong>${esc(e.kind)} · version ${e.version}</strong>${esc(e.actor)} · ${date(e.created_at)}<br>${esc(e.note)}</p>`).join('')}</div>`);return;}
 if(a==='export'){modal(`<h2>Export approved changes</h2><p>The packet contains approved fields that still pass the evidence checks, with original values and source references.</p><p>It is a manual review packet, not a JobAdder import file. A future live integration must compare current ATS values before changing them.</p><form id="export-form" data-id="${r.id}" data-version="${r.version}"><label class="check"><input name="confirmed" type="checkbox" required>I understand that export does not update JobAdder.</label><div class="actions"><button>Download review packet</button></div></form>`);return;}
 if(a==='calculate'){const form=$('#cost-form');if(!form.reportValidity())return;const x=values(form,costInputs);$('#cost-result').innerHTML='<hr>'+costResults(x);return;}
 if(a==='cost-example'){const form=$('#cost-form');const sample={name:'Illustrative only — not PRG costs',basis:'illustrative',evidence:'Example assumptions for learning the calculation',currentAnnual:6000,removablePercent:50,replacementAnnual:600,providerAnnual:900,supportAnnual:600,transitionCost:1200,recordsPerMonth:200,manualMinutes:5,assistedMinutes:3,hourlyCost:60};for(const [k,v]of Object.entries(sample))form.elements[k].value=v;$('#cost-result').innerHTML='<hr><p class="notice warning">Illustrative example only. None of these figures comes from a PRG invoice or measured pilot.</p>'+costResults(sample);return;}
 if(a==='study'){const s=state.studies.find(s=>s.id===b.dataset.id),p=s.payload;modal(`<h2>${esc(s.name)}</h2><p>${date(s.created_at)} · ${esc(p.basis||p.status)}</p>${s.type==='cost'?costResults(p.inputs):s.type==='pilot'?`<p>Audited accuracy: ${p.results.accuracy===null?'Not audited':decimal(p.results.accuracy)+'%'}<br>Useful coverage: ${decimal(p.results.coverage)}%<br>Acceptance: ${p.results.acceptance===null?'No proposed fields':decimal(p.results.acceptance)+'%'}<br>Net time change: ${decimal(p.results.hours)} hours<br>Cost per useful record: ${p.results.costPerUseful===null?'No useful records':money(p.results.costPerUseful)}<br>Critical errors: ${p.inputs.criticalErrors}</p>`:`<p>${esc(p.note)}</p><p>Owner: ${esc(p.owner)||'Unassigned'}</p>`}<p><strong>Evidence:</strong> ${esc(p.evidence)||'Not recorded'}</p><details><summary>Saved inputs</summary><pre class="code">${esc(JSON.stringify(p.inputs||p,null,2))}</pre></details>${btn('Download record','download-study','secondary',`data-id="${s.id}"`)}`);return;}
 if(a==='download-study')return download('prg-'+b.dataset.id+'.json',state.studies.find(s=>s.id===b.dataset.id));
 }catch(e){const target=$('#modal').open?$('#modal-error'):null;if(target)target.textContent=e.message;else toast(e.message);}finally{if(b.isConnected)b.disabled=false;}});
document.addEventListener('submit',async event=>{const form=event.target;if(form.id.startsWith('wb-')||!form.id.endsWith('-form'))return;event.preventDefault();if(!signed())return;const fd=new FormData(form),button=form.querySelector('button[type="submit"],button:not([type])'),err=form.querySelector('.form-error')||$('#modal-error');if(err)err.textContent='';if(button)button.disabled=true;try{
 if(form.id==='review-form')await api(`/enrichment/records/${form.dataset.id}/review`,{method:'POST',body:{version:Number(form.dataset.version),field:form.dataset.field,decision:form.dataset.decision,note:fd.get('note'),confirmed:fd.has('confirmed')}});
 else if(form.id==='edit-form'){const r=state.records.find(r=>r.id===form.dataset.id),p=structuredClone(r.payload);p.name=fd.get('name');p.stage=fd.get('stage');p.fields=p.fields.map((f,i)=>({...f,current:fd.get('current-'+i),proposed:fd.get('proposed-'+i),conflict:fd.has('conflict-'+i),resolution:fd.get('resolution-'+i),source:{type:fd.get('type-'+i),date:fd.get('date-'+i),reference:fd.get('reference-'+i),quote:fd.get('quote-'+i),identityConfirmed:fd.has('identity-'+i)}}));await api('/enrichment/records/'+r.id,{method:'PATCH',body:{version:Number(form.dataset.version),record:p}});}
 else if(form.id==='import-form'){const file=fd.get('file');if(file.size>60000)throw new Error('Keep the JSON file below 60 KB.');let input;try{input=JSON.parse(await file.text());}catch{throw new Error('The file is not valid JSON. Download the template for the required format.');}await api('/enrichment/records',{method:'POST',body:{syntheticOnly:fd.has('confirmed'),records:input.records}});}
 else if(form.id==='export-form'){const result=await api(`/enrichment/records/${form.dataset.id}/export`,{method:'POST',body:{version:Number(form.dataset.version),confirmed:fd.has('confirmed')}});download(result.packet.recordId+'-review.json',result.packet);}
 else if(form.id==='cost-form'||form.id==='pilot-form'){const type=form.id==='cost-form'?'cost':'pilot',input=values(form,type==='cost'?costInputs:pilotInputs);await api('/enrichment/studies',{method:'POST',body:{type,name:fd.get('name'),basis:fd.get('basis'),evidence:fd.get('evidence'),inputs:input}});}
 else if(form.id==='decision-form')await api('/enrichment/studies',{method:'POST',body:{type:'decision',...Object.fromEntries(fd)}});
 $('#modal').close();toast(form.id==='export-form'?'Review packet exported. JobAdder was not changed.':'Saved successfully.');await render();
 }catch(e){if(err)err.textContent=e.message;else toast(e.message);}finally{if(button?.isConnected)button.disabled=false;}});
document.addEventListener('change',event=>{if(['kind','status'].includes(event.target.id)){state[event.target.id]=event.target.value;$('#main').innerHTML=queue();}});
document.addEventListener('input',event=>{if(event.target.id==='search'){state.search=event.target.value;const pos=event.target.selectionStart;$('#main').innerHTML=queue();$('#search').focus();$('#search').setSelectionRange(pos,pos);}});
window.addEventListener('hashchange',()=>{if(location.hash==='#main'){$('#main').focus();return;}render();window.scrollTo(0,0);});
try{const info=await api('/me');state.me=info.user;$('#identity').innerHTML=`${esc(({admin:"Administrator",reviewer:"Reviewer",member:"Staff account"})[info.user.role]||"Staff account")} · <a href="#guide">Staff guide</a>${info.localDemo?' · <a href="/signin-with-chatgpt?role=author">Author</a> · <a href="/signin-with-chatgpt?role=reviewer">Reviewer</a> · <a href="/signin-with-chatgpt?role=owner">Owner</a>':''}`;}catch(e){if(e.status===503){state.authUnavailable=true;$('#identity').innerHTML='<a href="#guide">Staff sign-in pending</a>';}else if(e.status!==401)toast(e.message);}
await render();
